{
  "gateway": "amazon_native_action",
  "mode": "direct",
  "description": "Run any Amazon Ads endpoint through the native dispatcher. Surface-bounded generic tool; supports OAuth/profile routing, dry-runs, destructive confirmation, /adsApi/v1 OpenAPI batch endpoints, reporting, and nextToken aggregation.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "action": {
        "type": "string",
        "minLength": 1,
        "description": "Amazon Ads native action/tool name, e.g. ADS_API_SP_QUERY_CAMPAIGNS, amazon_ads_api_sp_query_campaigns, LIST_SP_CAMPAIGNS, or amazon_list_sp_campaigns."
      },
      "connection_id": {
        "type": "string",
        "format": "uuid",
        "description": "Optional Amazon Ads OAuth connection ID. Omit to use the active workspace connection or infer from profile_id."
      },
      "region": {
        "type": "string",
        "enum": [
          "NA",
          "EU",
          "FE"
        ],
        "description": "Amazon Ads region. Omit when profile_id was synced; the backend infers the region from amazon_selected_assets."
      },
      "profile_id": {
        "type": [
          "string",
          "number"
        ],
        "description": "Amazon Ads profile ID for Amazon-Advertising-API-Scope. Required for profile-scoped calls."
      },
      "path_params": {
        "type": "object",
        "additionalProperties": {},
        "description": "Templated path params. Friendly fields such as campaign_id, ad_group_id, report_id, ad_extension_id, and ad_association_id are also accepted."
      },
      "params": {
        "$ref": "#/properties/path_params",
        "description": "Native Amazon Ads params. For /adsApi/v1 query endpoints these are moved into the POST body."
      },
      "query": {
        "$ref": "#/properties/path_params",
        "description": "Explicit query params. For /adsApi/v1 query endpoints these are moved into the POST body."
      },
      "payload": {
        "$ref": "#/properties/path_params",
        "description": "Native Amazon Ads request body. Batch arrays use campaigns, adGroups, ads, targets, adExtensions, or adAssociations."
      },
      "aggregate_pages": {
        "type": "boolean",
        "default": false,
        "description": "Fetch additional /adsApi/v1 query pages by nextToken when true."
      },
      "max_pages": {
        "type": "integer",
        "minimum": 1,
        "maximum": 100,
        "default": 25,
        "description": "Page cap for aggregate_pages."
      },
      "max_items": {
        "type": "integer",
        "minimum": 1,
        "maximum": 50000,
        "description": "Cap returned arrays in the MCP result."
      },
      "confirmed": {
        "type": "boolean",
        "default": false,
        "description": "Required for destructive live calls."
      },
      "dry_run": {
        "type": "boolean",
        "default": true,
        "description": "Writes preview by default; read actions ignore it."
      },
      "skip_preflight": {
        "type": "boolean",
        "default": false,
        "description": "Bypass curated Amazon Ads write preflight."
      },
      "override_preflight": {
        "type": "boolean",
        "default": false,
        "description": "Alias for skip_preflight."
      },
      "result_fields": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Project MCP result records to these fields."
      },
      "fields": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Alias for result_fields unless a native fields parameter exists."
      },
      "compact": {
        "type": "boolean",
        "default": false,
        "description": "Remove null, empty string, and empty object values from the MCP result."
      }
    },
    "required": [
      "action"
    ],
    "additionalProperties": false,
    "$schema": "http://json-schema.org/draft-07/schema#"
  }
}
